using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class ArcherTests {
    static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);}
    public static void Run(string root){
        using var native=JsonDocument.Parse(File.ReadAllText(PackageLayout.FromBase("Content/Data/archer_rules.json")));int ranges=0,points=0;
        foreach(var v in native.RootElement.GetProperty("range_vectors").EnumerateArray()){if(ProjectileMath.WithinRange(v.GetProperty("dx").GetInt32(),v.GetProperty("dy").GetInt32(),v.GetProperty("squared").GetInt32())!=v.GetProperty("expected").GetBoolean())throw new Exception("Range differs from x86");ranges++;}
        foreach(var v in native.RootElement.GetProperty("trajectory_vectors").EnumerateArray()){int N(string name)=>v.GetProperty(name).GetInt32();int progress=0;foreach(var p in v.GetProperty("points").EnumerateArray()){var actual=ProjectileMath.Point(N("start_x"),N("start_y"),N("end_x"),N("end_y"),progress++);if(actual!=(p[0].GetInt32(),p[1].GetInt32()))throw new Exception("Trajectory differs from x86");points++;}}
        Check(ranges==1875&&points>9000,"1875 ranges and over 9000 projectile positions match original routines, including off-center launches");
        var visuals=new VisualCatalog();Check(visuals.ArcherVisual.Frames.Count==160&&visuals.ArcherVisual.FrameCount==10&&visuals.ArcherVisual.Frames.All(f=>f.Commands.Any(c=>c.Kind=="unit")),"archer attack uses 160 captured direction/phase combinations");
        Simulation Create(){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE01.ETA"));visuals.Apply(w);return new Simulation(Simulation.TrainingWorld(w,true));}
        Actor Hero(Simulation s)=>s.World.Units.First(u=>u.Owner==0&&u.Type==8);
        var sim=Create();var a=Hero(sim);var b=sim.World.Units.Last();int health=b.Health;int x=a.X,y=a.Y;
        Check(sim.CombatRule(8).Range*sim.CombatRule(8).Range==native.RootElement.GetProperty("range_squared").GetInt32(),"INI archer range squared matches original map instance");
        Check(sim.Attack(a,b),"archer receives explicit ranged attack order");for(int i=0;i<12;i++)sim.Step();Check(sim.Arrows.Count==1&&b.Health==health&&a.X==x&&a.Y==y,"archer fires within range without walking or instant damage");
        string flying=sim.Serialize();var resumed=Create();resumed.Restore(flying);for(int i=0;i<400;i++){sim.Step();resumed.Step();}Check(sim.Serialize()==resumed.Serialize(),"arrows in flight, retaliation and defeat resume deterministically");Check(b.Health==0&&a.Health>0&&sim.Arrows.Count==0,"ranged duel completes and removes spent projectiles");
        var stop=Create();var shooter=Hero(stop);var victim=stop.World.Units.Last();stop.Attack(shooter,victim);for(int i=0;i<12;i++)stop.Step();stop.Stop(shooter);for(int i=0;i<20;i++)stop.Step();Check(victim.Health==84&&(shooter.AttackTarget==-1||shooter.AutomaticDefense&&shooter.LastAttacker==victim.Slot),"stop cancels current order; fired arrow persists and incoming attack may trigger defense");
        var miss=Create();shooter=Hero(miss);victim=miss.World.Units.Last();miss.Attack(shooter,victim);for(int i=0;i<12;i++)miss.Step();miss.Stop(shooter);victim.Y+=1024;for(int i=0;i<25;i++)miss.Step();Check(victim.Health==100&&!miss.Arrows.Any(arrow=>arrow.SourceSlot==shooter.Slot),"arrow keeps fixed aim point and misses target that leaves the tile");
        var dead=Create();shooter=Hero(dead);victim=dead.World.Units.Last();dead.Attack(shooter,victim);for(int i=0;i<12;i++)dead.Step();shooter.Health=0;for(int i=0;i<20;i++)dead.Step();Check(victim.Health==84&&!dead.Arrows.Any(arrow=>arrow.SourceSlot==shooter.Slot),"fired projectile survives attacker defeat");var deadCopy=Create();deadCopy.Restore(dead.Serialize());Check(deadCopy.Serialize()==dead.Serialize(),"save after attacker defeat preserves completed projectile effects");
        var distant=Create();shooter=Hero(distant);victim=distant.World.Units.Last();victim.X=shooter.X+11*1024;Check(!distant.InAttackRange(shooter,victim),"eleven tiles exceeds original archer range of ten");distant.Attack(shooter,victim);distant.Step();Check(distant.Arrows.Count==0&&victim.Health==100,"out-of-range target receives no immediate shot");
        var same=Create();shooter=Hero(same);victim=same.World.Units.Last();victim.X=shooter.X;victim.Y=shooter.Y;same.Attack(shooter,victim);for(int i=0;i<12;i++)same.Step();var sameCopy=Create();sameCopy.Restore(same.Serialize());Check(sameCopy.Serialize()==same.Serialize(),"zero-length shot resolves without an invalid persistent projectile");
        foreach(var change in new Action<JsonNode>[]{n=>n["Arrows"]![0]!["Damage"]=999,n=>n["Arrows"]![0]!["Progress"]=-1,n=>n["Arrows"]![0]!["Progress"]=8,n=>n["Arrows"]![0]!["TargetSlot"]=99999,n=>n["Arrows"]![0]!["EndX"]=int.MaxValue,n=>n["Arrows"]=null,n=>n["Arrows"]!.AsArray().Add(n["Arrows"]![0]!.DeepClone())}){var node=JsonNode.Parse(flying)!;change(node);string before=resumed.Serialize();try{resumed.Restore(node.ToJsonString());throw new Exception("Malformed arrow accepted");}catch(InvalidDataException){}Check(resumed.Serialize()==before,"invalid projectile save rejected atomically");}
        var legacy=Create();var old=JsonNode.Parse(legacy.Serialize())!;old["Version"]=5;old.AsObject().Remove("Arrows");legacy.Restore(old.ToJsonString());Check(legacy.Arrows.Count==0,"v5 save loads with an empty projectile collection");
    }
}
